// Foundry VTT Macro: Нормализация ссылочных массивов (adds_items, prerequisites_*, chain_*)
// Чинит артефакты импорта: элементы, склеенные через «;» в одну строку
// («maneuver_a; maneuver_b»), лишние пробелы, пустые строки "" и дубликаты.
// По всем Item-компендиумам dedrel.*. Идемпотентно, повторный запуск безопасен.
//
// ВНИМАНИЕ: дедупликация может убрать НАМЕРЕННЫЙ дубль (например, два одинаковых
// natural-weapon в adds_items — «двойные когти»). Все снятые дубли выводятся в
// отчёт (console) отдельным списком — просмотрите и верните вручную, если нужно.
// Разбиение по «;» и чистку пустых/пробелов делаем всегда — они безопасны.
(async () => {
  if (!game.user.isGM) return ui.notifications.warn("Только для ГМа: правит компендиумы.");

  const FIELDS = [
    "adds_items",
    "chain_trigger_maneuvers",
    "prerequisites_attributes",
    "prerequisites_skills",
    "prerequisites_talents",
    "prerequisites_mutations",
    "prerequisites_bloodlines"
  ];

  // Массив -> {clean, removedDupes}: split ";", trim, drop empty, dedup (сохраняя порядок).
  function normalize(arr) {
    const flat = [];
    for (const el of arr) {
      if (typeof el !== "string") { flat.push(el); continue; }
      for (const part of el.split(";")) {
        const t = part.trim();
        if (t) flat.push(t);
      }
    }
    const seen = new Set();
    const clean = [];
    const removedDupes = [];
    for (const el of flat) {
      if (seen.has(el)) { removedDupes.push(el); continue; }
      seen.add(el);
      clean.push(el);
    }
    return { clean, removedDupes };
  }

  const packs = game.packs.filter(p => p.documentName === "Item" && p.collection.startsWith("dedrel."));
  if (!packs.length) return ui.notifications.error("Item-компендиумы dedrel.* не найдены.");

  let itemsFixed = 0, fieldsFixed = 0;
  const dupeReport = [];   // строки «Предмет / поле: удалён дубль key»

  for (const pack of packs) {
    const wasLocked = pack.locked;
    if (wasLocked) await pack.configure({ locked: false });

    const docs = await pack.getDocuments();
    const updates = [];
    for (const item of docs) {
      const sys = item.system ?? {};
      const patch = {};
      for (const field of FIELDS) {
        const arr = sys[field];
        if (!Array.isArray(arr) || !arr.length) continue;
        const { clean, removedDupes } = normalize(arr);
        if (JSON.stringify(clean) !== JSON.stringify(arr)) {
          patch[`system.${field}`] = clean;
          fieldsFixed++;
          for (const d of removedDupes) dupeReport.push(`${pack.collection} / ${item.name} / ${field}: дубль «${d}»`);
        }
      }
      if (Object.keys(patch).length) { patch._id = item.id; updates.push(patch); }
    }

    if (updates.length) {
      await Item.updateDocuments(updates, { pack: pack.collection });
      itemsFixed += updates.length;
    }
    if (wasLocked) await pack.configure({ locked: true });
  }

  const summary = `Нормализация массивов: предметов ${itemsFixed}, полей ${fieldsFixed}` +
    (dupeReport.length ? `, снято дублей ${dupeReport.length} (см. консоль)` : "");
  ui.notifications.info(summary);
  console.log(`[normalize_reference_arrays] ${summary}`);
  if (dupeReport.length) console.warn("[normalize_reference_arrays] СНЯТЫЕ ДУБЛИ — проверьте, не было ли намеренных:\n" + dupeReport.join("\n"));
})();
